function smokeBlocks(e,a,b){const ai=D.index(a.n),bi=D.index(b.n),ax=ai%e.scene.w,ay=Math.floor(ai/e.scene.w),bx=bi%e.scene.w,by=Math.floor(bi/e.scene.w),steps=Math.max(Math.abs(ax-bx),Math.abs(ay-by),1);for(let k=0;k<=steps;k++){const i=Math.round(ay+(by-ay)*k/steps)*e.scene.w+Math.round(ax+(bx-ax)*k/steps);if(e.fields.some(f=>f.type==='smoke'&&f.cells.includes(i)))return true;}return false;}
